        return Vector3(x - other.x, y - other.y, z - other.z);
    }

    // Multiplicação escalar
    Vector3 operator*(float scalar) const {
        return Vector3(x * scalar, y * scalar, z * scalar);
    }

    // Normalização do vetor
    Vector3 normalize() const {
        float magnitude = sqrt(x * x + y * y + z * z);
        return Vector3(x / magnitude, y / magnitude, z / magnitude);
    }
};

// Classe para representar o jogador
class Player {
public:
    Vector3 position; // Posição do jogador
    Vector3 forward; // Direção para a frente do jogador
    float health; // Vida do jogador
    bool isAlive; // Estado de vida do jogador
    float attackCooldown; // Tempo de cooldown do ataque

    // Construtor para inicializar o jogador
    Player(Vector3 position, Vector3 forward, float health)
        : position(position), forward(forward), health(health), isAlive(true), attackCooldown(0.0f) {}

    // Atualizar o estado do jogador
    void update(float deltaTime) {
        // Atualizar o cooldown do ataque
        if (attackCooldown > 0.0f) {
            attackCooldown -= deltaTime;
        }
    }

    // Verificar se o jogador está vivo
    bool isAliveCheck() const {
        return isAlive;
    }

    // Aplicar dano ao jogador
    void applyDamage(float damage) {
        if (isAlive) {
            health -= damage;
            if (health <= 0.0f) {
                health = 0.0f;
                isAlive = false;
            }
        }
    }
};

// Classe para representar a espada
class Sword {
public:
    Vector3 position; // Posição da espada
    Vector3 direction; // Direção da espada
    float length; // Comprimento da espada
    float damage; // Dano causado pela espada

    // Construtor para inicializar a espada
    Sword(Vector3 position, Vector3 direction, float length, float damage)
        : position(position), direction(direction), length(length), damage(damage) {}

    // Verificar se a espada atingiu um alvo
    bool hitCheck(const Vector3& targetPosition) const {
        // Calcular a distância entre a espada e o alvo
        Vector3 distance = targetPosition - position;
        float distanceMagnitude = sqrt(distance.x * distance.x + distance.y * distance.y + distance.z * distance.z);

        // Verificar se a distância é menor ou igual ao comprimento da espada
        if (distanceMagnitude <= length) {
            // Calcular o produto escalar entre a direção da espada e a direção para o alvo
            float dotProduct = (distance.x * direction.x + distance.y * direction.y + distance.z * direction.z) / (distanceMagnitude * length);

            // Verificar se o alvo está dentro do cone de ataque da espada
            if (dotProduct >= 0.5f) { // ângulo de 60 graus
                return true;
            }
        }

        return false;
    }
};

int main() {
    // Criar um jogador
    Player player(Vector3(0.0f, 0.0f, 0.0f), Vector3(1.0f, 0.0f, 0.0f), 100.0f);

    // Criar uma espada
    Sword sword(Vector3(0.0f, 0.0f, 0.0f), Vector3(1.0f, 0.0f, 0.0f), 1.5f, 20.0f);

    // Simular um ataque
    player.attackCooldown = 1.0f; // cooldown de 1 segundo

    // Loop de jogo
    float deltaTime = 0.01f; // tempo entre frames
    while (true) {
        // Atualizar o jogador
        player.update(deltaTime);

        // Verificar se o jogador pode atacar
        if (player.attackCooldown <= 0.0f) {
            // Atacar
            Vector3 targetPosition(1.0f, 0.0f, 0.0f); // posição do alvo
            if (sword.hitCheck(targetPosition)) {
                // Aplicar dano ao alvo
                player.applyDamage(sword.damage);
            }

            // Reiniciar o cooldown do ataque
            player.attackCooldown = 1.0f;
        }
    }

    return 0;
}
