// Classe para representar uma espada
class Sword {
public:
    Sword(float damage, float cooldown) : damage_(damage), cooldown_(cooldown), cooldownTimer_(0) {}

    // Atualiza o temporizador de cooldown
    void updateCooldown(float deltaTime) {
        if (cooldownTimer_ > 0) {
            cooldownTimer_ -= deltaTime;
            if (cooldownTimer_ < 0) {
                cooldownTimer_ = 0;
            }
        }
    }

    // Verifica se a espada está pronta para atacar
    bool isReadyToAttack() const {
        return cooldownTimer_ == 0;
    }

    // Ataca com a espada
    void attack(const Vector3& direction, Player& target) {
        if (isReadyToAttack()) {
            // Cálculo da direção do ataque
            Vector3 attackDirection = direction.normalize();

            // Verifica se o alvo está dentro do alcance da espada
            if (target.getPosition().magnitude() <= 1.5f) {
                // Aplica dano ao alvo
                target.applyDamage(damage_);
            }

            // Inicia o cooldown
            cooldownTimer_ = cooldown_;
        }
    }

private:
    float damage_;
    float cooldown_;
    float cooldownTimer_;
};

// Classe para gerenciar o combate
class CombatManager {
public:
    CombatManager(std::shared_ptr<Player> player1, std::shared_ptr<Player> player2)
        : player1_(player1), player2_(player2), sword_(std::make_shared<Sword>(10, 1)) {}

    // Atualiza o combate
    void update(float deltaTime) {
        // Atualiza o cooldown da espada
        sword_->updateCooldown(deltaTime);

        // Verifica se o jogador 1 está pronto para atacar
        if (sword_->isReadyToAttack()) {
            // Cálculo da direção do ataque
            Vector3 attackDirection = Vector3(1, 0, 0);

            // Ataca com a espada
            sword_->attack(attackDirection, *player2_);
        }
    }

private:
