    // Verifica se o cooldown está pronto
    bool isReady() const {
        return currentTime >= cooldownTime;
    }

    // Atualiza o tempo do cooldown
    void update(float deltaTime) {
        if (currentTime < cooldownTime) {
            currentTime += deltaTime;
        }
    }

    // Reinicia o cooldown
    void reset() {
        currentTime = 0;
    }

private:
    float cooldownTime;
    float currentTime;
