class Sword {
public:
    Sword(float length, float damage) : length(length), damage(damage), cooldown(0) {}

    // Atualiza o cooldown da espada
    void updateCooldown(float deltaTime) {
        if (cooldown > 0) {
            cooldown -= deltaTime;
            if (cooldown < 0) {
                cooldown = 0;
            }
        }
    }

    // Verifica se a espada está pronta para atacar
    bool isReadyToAttack() const {
        return cooldown == 0;
    }

    // Ataca com a espada
    void attack(const Player& player, const Player& target) {
        if (isReadyToAttack()) {
            // Cálculo da direção do ataque
            Vector3 attackDirection = player.getForwardVector();

            // Cálculo da posição do ataque
            Vector3 attackPosition = player.getPosition() + attackDirection * length;

            // Verifica se o alvo está dentro do alcance da espada
            if (isTargetInReach(target, attackPosition)) {
                // Aplica dano ao alvo
                target.applyDamage(damage);

                // Ativa o cooldown da espada
                cooldown = 1; // 1 segundo de cooldown
            }
        }
    }

    // Verifica se o alvo está dentro do alcance da espada
    bool isTargetInReach(const Player& target, const Vector3& attackPosition) const {
        // Cálculo da distância entre o ataque e o alvo
        Vector3 distanceVector = target.getPosition() - attackPosition;
        float distance = distanceVector.magnitude();

        // Verifica se a distância é menor ou igual ao comprimento da espada
        return distance <= length;
    }

private:
    float length;
    float damage;
    float cooldown;
};

