            cooldownTimer = 0;
        }
    }

    // Verifica se a espada está pronta para atacar
    bool isReadyToAttack() const {
        return cooldownTimer == 0;
    }

    // Ataca com a espada
    void attack(Player& target) {
        if (isReadyToAttack()) {
            // Cálculo da direção do ataque
            Vector3 attackDirection = direction.normalize();

            // Cálculo da posição do ataque
            Vector3 attackPosition = position + attackDirection * length;

            // Verifica se o ataque acertou o alvo
            if (std::abs((target.position - attackPosition).magnitude()) < 1.0f) {
                target.applyDamage(10.0f);
            }

            // Reinicia o cooldown
            cooldownTimer = cooldown;
        }
    }
};

// Classe para gerenciar o combate
class CombatManager {
public:
    std::vector<std::unique_ptr<Player>> players;
    std::vector<std::unique_ptr<Sword>> swords;

    CombatManager() {}

    // Adiciona um jogador ao combate
    void addPlayer(std::unique_ptr<Player> player) {
        players.push_back(std::move(player));
    }

    // Adiciona uma espada ao combate
    void addSword(std::unique_ptr<Sword> sword) {
        swords.push_back(std::move(sword));
    }

    // Atualiza o estado do combate
    void update(float deltaTime) {
        for (auto& player : players) {
            player->update(deltaTime);
        }

        for (auto& sword : swords) {
            sword->update(deltaTime);
        }
    }

    // Verifica se o combate está em andamento
    bool isCombatOngoing() const {
        for (const auto& player : players) {
            if (player->isAliveCheck()) {
                return true;
            }
        }

        return false;
    }
};

int main() {
    // Criação do gerenciador de combate
    CombatManager combatManager;

    // Criação de jogadores
    std::unique_ptr<Player> player1 = std::make_unique<Player>(Vector3(0, 0, 0), Vector3(1, 0, 0), 100.0f);
    std::unique_ptr<Player> player2 = std::make_unique<Player>(Vector3(5, 0, 0), Vector3(-1, 0, 0), 100.0f);

    // Criação de espadas
    std::unique_ptr<Sword> sword1 = std::make_unique<Sword>(Vector3(0, 0, 0), Vector3(1, 0, 0), 2.0f, 1.0f);
    std::unique_ptr<Sword> sword2 = std::make_unique<Sword>(Vector3(5, 0, 0), Vector3(-1, 0, 0), 2.0f, 1.0f);

    // Adição de jogadores e espadas ao combate
    combatManager.addPlayer(std::move(player1));
    combatManager.addPlayer(std::move(player2));
    combatManager.addSword(std::move(sword1));
    combatManager.addSword(std::move(sword2));

    // Simulação do combate
    float deltaTime = 0.01f;
    while (combatManager.isCombatOngoing()) {
        combatManager.update(deltaTime);

        // Ataque com a espada
        for (auto& sword : combatManager.swords) {
            for (auto& player : combatManager.players) {
                if (player->isAliveCheck() && sword->isReadyToAttack()) {
                    sword->attack(*player.get());
                }
            }
        }
    }

    return 0;
}

